class Solution {
  public int numberOfStableArrays(int zero, int one, int limit) {
    final long MOD = 1_000_000_007L;
    // endZero[i][j] / endOne[i][j]: stable arrays with i zeros and j ones ending in 0 / 1
    long[][] endZero = new long[zero + 1][one + 1], endOne = new long[zero + 1][one + 1];
    for (int i = 1; i <= Math.min(zero, limit); i++) endZero[i][0] = 1;
    for (int j = 1; j <= Math.min(one, limit); j++) endOne[0][j] = 1;
    for (int i = 1; i <= zero; i++) {
      for (int j = 1; j <= one; j++) {
        long zeros = endZero[i - 1][j] + endOne[i - 1][j];
        if (i > limit) zeros -= endOne[i - limit - 1][j];
        endZero[i][j] = ((zeros % MOD) + MOD) % MOD;
        long ones = endOne[i][j - 1] + endZero[i][j - 1];
        if (j > limit) ones -= endZero[i][j - limit - 1];
        endOne[i][j] = ((ones % MOD) + MOD) % MOD;
      }
    }
    return (int) ((endZero[zero][one] + endOne[zero][one]) % MOD);
  }
}
